      {
        "start": 49.2,
        "end": 50.6,
        "text": "用来先判断狗子"
      },
      {
        "start": 50.6,
        "end": 51.4,
        "text": "哪里虚"
      },
      {
        "start": 51.4,
        "end": 52.2,
